class AIDStore(object):

    _instance = None
    _aid_store = {}

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            cls._instance = super(AIDStore, cls).__new__(cls, *args, **kwargs)
        return cls._instance

    def init_store(self):
        self._aid_store = {}

    def get_aid(self, pdn_name):
        return self._aid_store.get(pdn_name, None)

    def pop_aid(self, pdn_name):
        return self._aid_store.pop(pdn_name)

    def store_aid(self, pdn_name, aid):
        self._aid_store[pdn_name] = aid
